// Normalize any price payload into a flat list of {id, name, price, url, currency}.
// Edit the mapping below to match YOUR source's field names.
const input = $input.first().json;

const raw = input.products || input.items || input.data || (Array.isArray(input) ? input : []);

const out = raw.map((r) => {
  const id = String(r.id ?? r.sku ?? r.productId ?? r.url ?? '');
  return {
    json: {
      id,
      name: r.title ?? r.name ?? r.productName ?? '(no name)',
      price: Number(r.price ?? r.currentPrice ?? r.amount ?? 0),
      currency: r.currency ?? 'USD',
      url: r.url ?? r.link ?? r.permalink ?? '',
      checkedAt: new Date().toISOString()
    }
  };
}).filter((x) => x.json.id && x.json.price > 0);

return out;

// Compare current prices against the previous run stored in the sheet.
// Builds a lookup of previous prices, then flags drops on the current items.
const DROP_PCT = Number($vars.DROP_THRESHOLD_PCT || 10); // alert if price fell >= this %

// Previous rows come from the 'Read Previous Prices' node (may be empty on run 1).
let prevRows = [];
try {
  prevRows = $('Read Previous Prices').all().map((i) => i.json).filter((r) => r && r.id != null);
} catch (e) {
  prevRows = [];
}
const prev = {};
for (const r of prevRows) {
  prev[String(r.id)] = {
    price: Number(r.price ?? 0),
    lowestPrice: Number(r.lowestPrice ?? r.price ?? 0)
  };
}

// Current products come from 'Normalize Products'.
const current = $('Normalize Products').all().map((i) => i.json);

const out = current.map((c) => {
  const p = prev[String(c.id)];
  const oldPrice = p ? p.price : null;
  const prevLowest = p ? p.lowestPrice : c.price;
  const lowestPrice = Math.min(prevLowest || c.price, c.price);

  let changePct = 0;
  if (oldPrice && oldPrice > 0) {
    changePct = Math.round(((c.price - oldPrice) / oldPrice) * 1000) / 10; // 1 decimal
  }
  const isDrop = oldPrice != null && changePct <= -DROP_PCT;

  return {
    json: {
      ...c,
      oldPrice,
      changePct,
      lowestPrice,
      isAllTimeLow: c.price <= lowestPrice,
      isDrop
    }
  };
});

return out;
